<script>
import { STATIONS } from '../../utils/globalConst.js'

export default {
  name: 'SvgMap',
  emits: ["station-selected"],
  data() {
    return {
      STATIONS,
    }
  },
  props: {
    selectedId: {
        type: Array,  // now it's an array
        default: () => [] 
    },
  },
  methods: {
    selectStation(event) {
        const id = event.target.id
        console.log("Clicked station:", id)
        this.$emit("station-selected", id)
    }
  }
}
</script>
<style>
.station:hover {
    cursor: pointer
}
.is-selected {
  fill: red;
}
.is-bouncing {
  display: inline-block;
  animation: bounce 1s infinite
}

@keyframes bounce {
  0%, 20%, 50%, 80%, 100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-5px); /* move up */
  }
  60% {
    transform: translateY(-1px); /* smaller bounce down */
  }
}
</style>